  riesgos_residuales: { que: "Reevalúa los riesgos residuales que persisten después de aplicar los controles.", guia: "En actividad describe la tarea ya controlada; en área dónde se ejecuta; en entorno las condiciones actuales; en N° trabajadores los expuestos; y en detalle indica los controles ya implementados y el nivel de riesgo que aún permanece tras ellos.", tip: "Detalla con claridad los controles ya aplicados para que la reevaluación del riesgo residual sea realista.", ej: { actividad: "Trabajo en altura con arnés", area: "Fachada de edificio", entorno: "Plataforma a 10 metros con línea de vida", n_trabajadores: "ej. 4", detalle: "Arnés y línea de vida instalados, persiste riesgo por viento fuerte" } },
  severidad_locativa: { que: "Valora la severidad de los peligros locativos del lugar de trabajo y sus controles.", guia: "En actividad indica la labor que se realiza en el espacio; en área la zona o instalación; en entorno el estado de pisos, escaleras, orden y señalización; en N° trabajadores los expuestos; y en detalle menciona condiciones como pisos irregulares, falta de orden, mala iluminación, obstáculos o desniveles.", tip: "Describe el estado real de pisos, accesos y orden para valorar mejor la severidad del daño potencial.", ej: { actividad: "Tránsito y abastecimiento interno", area: "Pasillos de almacén", entorno: "Pisos irregulares con cajas obstruyendo el paso", n_trabajadores: "ej. 10", detalle: "Desniveles sin señalizar, baja iluminación, riesgo de caídas y tropiezos" } },

