  inv_factores_personales: { que: "Genera un análisis de los factores personales del trabajador que influyeron en el accidente.", guia: "En actividad coloca el accidente investigado. En área la zona de trabajo. En entorno el contexto laboral (jornada, presión, fatiga). En N° trabajadores los afectados. En detalle describe el hecho y aspectos del trabajador como experiencia, capacitación o estado físico.", tip: "Analiza fatiga, experiencia y capacitación sin juzgar a la persona, busca explicar no culpar.", ej: { actividad: "Corte con esmeril angular en mano", area: "Taller de mantenimiento mecánico", entorno: "Jornada extendida de 10 horas, alta carga de trabajo", n_trabajadores: "ej. 2", detalle: "Operario con 2 semanas de experiencia usa esmeril sin guarda por fatiga al final del turno" } },
  inv_ishikawa: { que: "Genera un diagrama de Ishikawa que organiza las causas en las 6M (mano de obra, máquina, método, material, medio y medición).", guia: "En actividad coloca el accidente investigado. En área el proceso afectado. En entorno las condiciones físicas y organizativas. En N° trabajadores los involucrados. En detalle describe el hecho y las posibles causas por cada M.", tip: "Aporta datos para las 6 categorías para que el diagrama quede completo y balanceado.", ej: { actividad: "Volcadura de montacargas", area: "Almacén central - zona de despacho", entorno: "Piso irregular, alta rotación de carga, espacio reducido", n_trabajadores: "ej. 5", detalle: "Montacargas vuelca al girar con carga elevada en piso desnivelado sin demarcar" } },
